learn=[('Receive real text deltas', 'Enable includePartialMessages. Check stream_event, content_block_delta and text_delta before accumulating text. Each callback receives a new chunk, not the full response.'), ('Scope blocks correctly', 'Identify each block by API message ID and block index. Tool-use IDs identify execution across messages. Index zero can be reused in the next message.'), ('Assemble tool input separately', 'Accumulate input_json_delta partial_json independently for each tool block. Parse only when its content_block_stop arrives. A stopped input block does not prove successful execution.'), ('Observe actual execution', 'PreToolUse marks execution running. PostToolUse confirms success; native feedback records errors. Compare delayed and denied Read experiments.'), ('Reconcile complete messages', 'Complete assistant content blocks provide authoritative text. Replace provisional block content instead of appending it again. Markdown is sanitized before rendering.'), ('Forward and validate', 'The host sends actual observations through browser SSE. Keep raw events for inspection. Structured chunks are unvalidated; consume result.structured_output. Main-session deltas do not forward subagent tokens.')]
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3136\n# Windows only, if needed:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'
runsteps=[('Prerequisites', 'Use Node.js 24+, API credit and a supported model. On Windows configure Git Bash when required. Python is only needed to rebuild student pages.', 'node --version\nnpm --version'), ('Install and configure .env', 'Install dependencies, preserve an existing configuration file and enter your own model key privately.', 'cd .\\agent-sdk\\lesson36-streaming-output\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start the application', 'Leave the terminal running and open the printed URL. Use all five navigation buttons.', 'npm start\n# http://127.0.0.1:3136'), ('Compare complete and partial output', 'Run Complete only, Text deltas and Typewriter. Watch actual chunks arrive. Complete Markdown renders with headings, lists and coloured source pages.', 'npm run sample:env -- complete\nnpm run sample:env -- text\nnpm run sample:env -- typewriter'), ('Inspect tool input and execution', 'Compare one Read, two Reads, delayed Read and denied Read. Inspect indexed JSON and real execution callbacks. Delayed Read uses an explicit 3.5-second classroom hook delay.', 'npm run sample:env -- read\nnpm run sample:env -- two-reads\nnpm run sample:env -- slow-read\nnpm run sample:env -- denied'), ('Validate and reconcile', 'Inspect structured_output from the final result. Run Reconcile and compare complete assistant text with rendered blocks. Download actual observations and run offline tests.', 'npm run sample:env -- structured\nnpm run sample:env -- reconcile\nnpm test')]
specs=[('Validate the experiment', 'src/modes.ts', 'export function validateConfig', 'The host accepts only a listed mode. The browser cannot replace tool scope, prompts or SDK options.', 0, 1, 7), ('Enable partial output', 'src/agent.ts', 'permissionMode:', 'includePartialMessages enables raw output events. Input remains one string prompt; output streaming is independent of streaming input.', 1, 2, 5), ('Start the actual query', 'src/agent.ts', 'const q = query', 'One real Query owns model and tool orchestration. Drain its output iterator through the final result.', 1, 2, 3), ('Apply three nested guards', 'src/agent.ts', 'if (message.type === "stream_event")', 'Distinguish the SDK wrapper, raw event type and delta type before treating a chunk as text.', 2, 1, 9), ('Identify the API message', 'src/assembler.ts', 'if (event.type === "message_start")', 'Record the API message identifier. Block indices are scoped to this message, so index zero in a later turn remains distinct.', 2, 4, 5), ('Accumulate indexed deltas', 'src/assembler.ts', 'const block = this.blocks.get(this.key(event.index));', 'Look up the current message and block index. Append text and partial JSON to separate buffers.', 2, 4, 5), ('Parse stopped tool input', 'src/assembler.ts', 'block.stopped = true;', 'Only parse JSON after the content block stops. An incomplete or malformed buffer cannot be reported as completed input.', 4, 4, 9), ('Scope actual Read execution', 'src/agent.ts', 'const allowed =', 'Permit only the disposable lesson.txt Read. Denied calls produce real tool feedback without successful execution.', 2, 3, 5), ('Confirm successful execution', 'src/agent.ts', 'if (input.hook_event_name === "PostToolUse")', 'Actual PostToolUse marks execution completed. Receiving an input block is a separate stage.', 3, 1, 3), ('Accept authoritative content', 'src/assembler.ts', 'block.authoritative = true;', 'Complete SDK text replaces the provisional block. Preserve complete content as the source of truth.', 2, 4, 4), ('Consume the final result', 'src/agent.ts', 'structured =', 'Only a successful final result supplies validated structured_output. Raw JSON-looking chunks remain provisional.', 2, 1, 4), ('Forward browser SSE', 'src/server.ts', 'const emit =', 'The local host serializes actual observations into SSE frames. UTF-8 decoding and frame buffering preserve arbitrary network chunk boundaries.', 1, 0, 4), ('Render without duplicated text', 'src/client.ts', 'if (b.authoritative)', 'Render sanitized Markdown for complete text. Partial text uses textContent. Replace snapshots instead of appending complete content twice.', 4, 0, 7)]
document('/','Streaming output. <em>See it arrive.</em>','Receive actual text and tool deltas; reconcile complete SDK messages.','<div class="flow"><div><b>01 · Receive</b><p>Actual SDK deltas</p></div><span>→</span><div><b>02 · Assemble</b><p>Message and block identity</p></div><span>→</span><div><b>03 · Confirm</b><p>Complete messages and results</p></div></div><section class="panel" id="controls"><h2>Explore streaming output</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Output experiment</label><select id="mode"><option value="complete">Complete only · no token events</option><option value="text">Text deltas · incremental paragraphs</option><option value="typewriter">Typewriter · formatted Markdown</option><option value="read">Tool JSON · one real Read</option><option value="two-reads">Indexed blocks · two sequential Reads</option><option value="slow-read">Tool lifecycle · delayed actual Read</option><option value="denied">Tool lifecycle · actual denial</option><option value="structured">Structured output · validated final result</option><option value="reconcile">Reconcile · complete blocks without duplicates</option></select><button id="run" class="primary" disabled>Run output experiment →</button><p class="meta">Every response uses a real SDK query. Only the disposable lesson.txt Read is permitted. Raw deltas are provisional; complete blocks confirm content. Each query has a $0.45 SDK budget threshold.</p></section><div class="workspace"><section class="panel" id="chat-panel"><h2 id="status" aria-live="polite">Ready</h2><p>Actual text deltas: <strong id="delta-count">0</strong></p><div id="conversation"></div></section><section class="panel" id="option-panel"><h2>Options actually passed</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre><p>Compare includePartialMessages with the actual raw event count.</p></section></div><section class="step" id="tool-panel"><h2>Actual tool execution status</h2><pre class="json-view"><code id="tool-status" class="language-json">[]</code></pre><p>Input received ≠ execution complete. Only actual successful tool callbacks produce completed.</p></section><section class="step" id="blocks-panel"><h2>Indexed text and tool-input blocks</h2><pre class="json-view"><code id="block-data" class="language-json">[]</code></pre><p>Tool JSON is assembled per message ID and index; parse it after the input block stops.</p></section><section class="step" id="authoritative-panel"><h2>Authoritative complete SDK text</h2><div id="authoritative"></div><p>Each complete text block replaces its provisional content in the live response. It is not appended twice.</p></section><section class="step" id="results-panel"><h2>Final SDK result</h2><pre class="json-view"><code id="result" class="language-json">{}</code></pre></section><section class="step" id="structured-panel"><h2>Validated structured result</h2><pre class="json-view"><code id="structured" class="language-json">null</code></pre><p>Use result.structured_output. Raw JSON-looking deltas are not validated structured data.</p></section><section class="step" id="observation-panel"><h2>Inspect actual raw events</h2><label for="observation-select">Observed arrival sequence</label><select id="observation-select"><option>No observations yet</option></select><pre class="json-view"><code id="selected-observation" class="language-json">{}</code></pre></section><section class="step" id="evidence-panel"><h2>Independent run evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><button id="download">Download actual observations</button></section>','<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Understand real-time output, indexed blocks and authoritative content.',cards(learn))
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your .env configuration</h2>'+snippet(env,'dotenv')+'<p>Only your model key is required. Keep it local and restart after edits. Existing shell variables take precedence.</p></section><section class="note"><h3>Troubleshooting</h3><p>Use Node 24+, API credit and a supported model. Configure Git Bash on Windows if requested. If the port is occupied, use the printed existing-app URL or change PORT. Select an output experiment and watch actual delta arrival. Compare complete-only output with partial events. Change PORT if 3136 is occupied. The delayed Read includes a deliberate 3.5-second classroom hook delay.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install the SDK, configure your key and run the classroom comparisons.',body)
steps=[];arrows=[];lanes=['Student UI','TypeScript host','Agent SDK Query','Read tool + fixture','Indexed output blocks']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 36 · Receive → assemble → confirm → render</text>']
for x,label,colour in zip(xs,lanes,['#087fff','#8838ff','#00a977','#8838ff','#ee5425']):svg.append(f'<rect x="{x-150}" y="90" width="300" height="80" rx="16" fill="{colour}"/><text x="{x}" y="139" text-anchor="middle" font-family="Arial" font-size="27" fill="white">{escape(label)}</text><path d="M{x} 170 V1550" stroke="#aec6df" stroke-dasharray="8 7"/>')
for i,(a,b,label) in enumerate(arrows):
 x1,x2=xs[a],xs[b];y=245+i*98;path=f'M{x1} {y} h65 v24 h-65' if a==b else f'M{x1} {y} H{x2}';svg.append(f'<text x="{min(x1,x2)+10}" y="{y-18}" fill="#142d53" font-family="Arial" font-size="24">{escape(label)}</text><path d="{path}" stroke="#087fff" stroke-width="3" marker-end="url(#arrow)"/>')
(PUBLIC/'architecture.svg').write_text(''.join(svg)+'</svg>',encoding='utf-8')
walk=''
for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'])+'</section>'
document('/architecture.html','Architecture and <em>UML workflow.</em>','Every workflow step includes its corresponding coloured code excerpt.','<p class="note">The diagram groups text streaming, real tool execution and final structured output. The SDK owns orchestration. Complete assistant blocks confirm provisional text; input completion is separate from tool execution.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen source-linked output workflow steps"></div>'+walk)

reference=[('Raw event reference', 'message_start, content_block_start, content_block_delta, content_block_stop, message_delta and message_stop describe raw API output. Events are not accumulated messages.'), ('Execution boundary', 'content_block_stop completes generation of a content block. It does not prove a tool ran or succeeded. This app uses actual execution hooks and native tool feedback.'), ('Subagent limitation', 'Partial stream events are forwarded for the main session only. Complete messages can identify subagent output through parent_tool_use_id. This classroom app does not launch subagents.'), ('Structured output', 'Unvalidated text or tool-input chunks must not be presented as validated objects. The structured experiment uses outputFormat and consumes the actual result.structured_output.'), ('Cut streams', 'An open tool input without its content_block_stop remains incomplete. Offline unit fixtures test truncated and malformed input; the live browser experiments use the actual SDK.'), ('Teaching boundaries', 'The app permits only one fixed Read fixture; it cannot edit or run shell tools. It uses isolated temporary directories, checks the fixture and cleans up after each run. A budget threshold is not a prepaid cap.')]
document('/walkthrough.html','How the app <em>was built.</em>','Every architecture step has source-linked coloured code.',cards(reference)+walk)
readme='# Claude Agent SDK · Lesson 36 · Streaming output in real time\n\nFive linked student pages, large text, actual SDK experiments and coloured code in all thirteen UML steps.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n' for a,b in learn)
readme+='\n## Configure and run\n\n```powershell\ngit clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson36-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson36-app\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n```\n\nFrom presentations use `cd .\\agent-sdk\\lesson36-streaming-output`. Open http://127.0.0.1:3136 and keep the terminal running. Node.js 24+, API credit and model access are required. Windows may require Git Bash.\n\n## Create your .env file\n\nPreserve an existing file. Enter your own model key, then restart. Existing shell values take precedence.\n\n```dotenv\n'+env+'\n```\n\nNo GitHub token or Managed Agents IDs are required. Secrets, dependencies and teaching media stay outside Git.\n\n## Run the experiments\n\n'
for title,explanation,code in runsteps[3:]:readme+=f'### {title}\n\n{explanation}\n\n```powershell\n{code}\n```\n\n'
readme+='## How the app was built\n\n'
for step in steps:readme+=f'### {step["number"]}. {step["title"]}\n\n{step["explanation"]}\n\nSource: `{step["source"]}`, selected lines {step["firstLine"]}–{step["lastLine"]}. Surrounding code omitted.\n\n```typescript\n{step["code"]}\n```\n\n'
readme+='## Reference topics and limits\n\n'+''.join(f'- {a}: {b}\n' for a,b in reference)+'\n## References\n\n- [Official SDK streaming-output documentation](https://code.claude.com/docs/en/agent-sdk/streaming-output)\n- [TypeScript SDK reference](https://code.claude.com/docs/en/agent-sdk/typescript)\n\nRegenerate student pages with `python scripts/build-pages.py`. Run `npm test` for offline boundaries, review lifecycle, workspace and startup checks.\n'
(APP/'README.md').write_text(readme,encoding='utf-8')
print('Built five Lesson 36 pages and thirteen source-linked UML steps.')

